export function gerarNomeSequencial(nomesExistentes) {
  let contador = 1;
  let nome = "Novo Fluxo";

  while (nomesExistentes.includes(nome)) {
    contador += 1;
    nome = `Fluxo (${contador})`;
  }

  return nome;
}

export function nomeDuplicado(nomesExistentes, nomeProposto, idAtual) {
  return nomesExistentes.some(f => f.nome === nomeProposto && f.id !== idAtual);
}
